/*
 * Copyright (c) 2023, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import React from 'react';
import loadable from '@loadable/component';
import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

// Components
import { Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
import { configureRoutes } from '@salesforce/retail-react-app/app/utils/routes-utils';
import { routes as _routes } from '@salesforce/retail-react-app/app/routes';

const fallback = <Skeleton height="75vh" width="100%" />;

// Create your pages here and add them to the routes array
// Use loadable to split code into smaller js chunks
const Home = loadable(() => import('./pages/home'), { fallback });
const MyNewRoute = loadable(() => import('./pages/my-new-route'));
const Experience = loadable(() => import('./pages/experience'), { fallback });
const ContentfulPreview = loadable(() => import('./pages/contentfulPreview'), { fallback });

/*
 * The PDP override is reached through this explicit entry, not through the overrides
 * resolver. That resolver only redirects imports that *name* `@salesforce/retail-react-app`;
 * the base `app/routes.jsx` loads its PDP with a relative `import('./pages/product-detail')`,
 * which is never redirected. Without the route below, `overrides/app/pages/product-detail`
 * is dead code and the base page renders instead.
 */
const ProductDetail = loadable(() => import('./pages/product-detail'), { fallback });

const routes = [
  {
    path: '/',
    component: Home,
    exact: true,
  },
  {
    path: '/my-new-route',
    component: MyNewRoute,
  },
  // Must precede `..._routes` — the base array carries its own '/product/:productId'
  // entry pointing at the base page, and `configureRoutes` keeps the first match.
  {
    path: '/product/:productId',
    component: ProductDetail,
  },
  ..._routes,
  // Contentful Live Preview — must be before /:slug so it takes priority.
  {
    path: '/preview',
    component: ContentfulPreview,
    exact: true,
  },
  // Contentful Studio/Experience pages — fallback after all SFCC routes.
  // `configureRoutes` strips PWA Kit's '*' catch-all so this is safely reached only for paths no other route matched.
  {
    path: '/:slug',
    component: Experience,
  },
];

export default () => {
  const config = getConfig();
  return configureRoutes(routes, config, {
    ignoredRoutes: ['/callback', '*'],
  });
};

/*
 * Copyright (c) 2022, Salesforce, Inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

import React, {useEffect} from 'react'
import {useIntl, FormattedMessage} from 'react-intl'
import {useLocation} from 'react-router-dom'

// Components
import {
    Box,
    Button,
    SimpleGrid,
    HStack,
    VStack,
    Text,
    Flex,
    Stack,
    Container,
    Link,
    Heading
} from '@salesforce/retail-react-app/app/components/shared/ui'

// Project Components
import Hero from '@salesforce/retail-react-app/app/components/hero'
import Seo from '@salesforce/retail-react-app/app/components/seo'
import Section from '@salesforce/retail-react-app/app/components/section'
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller'
import Island from '@salesforce/retail-react-app/app/components/island'

// Others
import {getAssetUrl} from '@salesforce/pwa-kit-react-sdk/ssr/universal/utils'
import {heroFeatures, features} from '@salesforce/retail-react-app/app/pages/home/data'

//Hooks
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein'
import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud'

// Constants
import {
    HOME_SHOP_PRODUCTS_CATEGORY_ID,
    HOME_SHOP_PRODUCTS_LIMIT,
    MAX_CACHE_AGE,
    STALE_WHILE_REVALIDATE
} from '@salesforce/retail-react-app/app/constants'
import {useServerContext} from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks'
import {useProductSearch} from '@salesforce/commerce-sdk-react'

/**
 * This is the home page for Retail React App.
 * The page is created for demonstration purposes.
 * The page renders SEO metadata and a few promotion
 * categories and products, data is from local file.
 */
const Home = () => {
    const intl = useIntl()
    const einstein = useEinstein()
    const dataCloud = useDataCloud()
    const {pathname} = useLocation()

    const {res} = useServerContext()
    if (res) {
        res.set(
            'Cache-Control',
            `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`
        )
    }

    const {data: productSearchResult, isLoading} = useProductSearch({
        parameters: {
            allImages: true,
            allVariationProperties: true,
            expand: ['promotions', 'variations', 'prices', 'images', 'custom_properties'],
            limit: HOME_SHOP_PRODUCTS_LIMIT,
            perPricebook: true,
            refine: [`cgid=${HOME_SHOP_PRODUCTS_CATEGORY_ID}`, 'htype=master']
        }
    })

    /**************** Einstein ****************/
    useEffect(() => {
        einstein.sendViewPage(pathname)
        dataCloud.sendViewPage(pathname)
    }, [])

    return (
        <Box data-testid="home-page" layerStyle="page">
            <Heading as="h1" srOnly>
                <FormattedMessage defaultMessage="Home" id="home.title.home" />
            </Heading>
            <Seo
                title="Home Page"
                description="Commerce Cloud Retail React App"
                keywords="Commerce Cloud, Retail React App, React Storefront"
            />

            <Island hydrateOn={'visible'}>
                <Hero
                    title={intl.formatMessage({
                        defaultMessage: 'The React PWA Starter Store for Retail',
                        id: 'home.title.react_starter_store'
                    })}
                    img={{
                        src: getAssetUrl('static/img/hero.png'),
                        alt: 'npx pwa-kit-create-app',
                        fetchPriority: 'high'
                    }}
                    actions={
                        <Stack spacing={{base: 4, sm: 6}} direction={{base: 'column', sm: 'row'}}>
                            <Button
                                as={Link}
                                href="https://developer.salesforce.com/docs/commerce/pwa-kit-managed-runtime/guide/getting-started.html"
                                target="_blank"
                                width={{base: 'full', md: 'inherit'}}
                                paddingX={7}
                                _hover={{textDecoration: 'none'}}
                            >
                                <FormattedMessage
                                    defaultMessage="Get started"
                                    id="home.link.get_started"
                                />
                            </Button>
                        </Stack>
                    }
                />
            </Island>

            <Island hydrateOn={'visible'}>
                <Section
                    background={'gray.50'}
                    marginX="auto"
                    paddingY={{base: 8, md: 16}}
                    paddingX={{base: 4, md: 8}}
                    borderRadius="base"
                    width={{base: '100vw', md: 'inherit'}}
                    position={{base: 'relative', md: 'inherit'}}
                    left={{base: '50%', md: 'inherit'}}
                    right={{base: '50%', md: 'inherit'}}
                    marginLeft={{base: '-50vw', md: 'auto'}}
                    marginRight={{base: '-50vw', md: 'auto'}}
                >
                    <SimpleGrid
                        columns={{base: 1, md: 1, lg: 3}}
                        spacingX={{base: 1, md: 4}}
                        spacingY={{base: 4, md: 14}}
                    >
                        {heroFeatures.map((feature, index) => {
                            const featureMessage = feature.message
                            return (
                                <Link key={index} target="_blank" href={feature.href}>
                                    <Box
                                        background={'white'}
                                        boxShadow="0px 2px 2px rgba(0, 0, 0, 0.1)"
                                        borderRadius={'4px'}
                                    >
                                        <HStack>
                                            <Flex
                                                paddingLeft={6}
                                                height={24}
                                                align={'center'}
                                                justify={'center'}
                                            >
                                                {feature.icon}
                                            </Flex>
                                            <Text fontWeight="700">
                                                {intl.formatMessage(featureMessage.title)}
                                            </Text>
                                        </HStack>
                                    </Box>
                                </Link>
                            )
                        })}
                    </SimpleGrid>
                </Section>
            </Island>

            {productSearchResult && (
                <Island hydrateOn={'visible'}>
                    <Section
                        padding={4}
                        paddingTop={16}
                        title={intl.formatMessage({
                            defaultMessage: 'Shop Products',
                            id: 'home.heading.shop_products'
                        })}
                        subtitle={intl.formatMessage(
                            {
                                defaultMessage:
                                    'This section contains content from the catalog. {docLink} on how to replace it.',
                                id: 'home.description.shop_products',
                                description:
                                    '{docLink} is a html button that links the user to https://sfdc.co/business-manager-manage-catalogs'
                            },
