112	import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
113	import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';
114	
115	/*
116	 * `@salesforce/retail-react-app` ships no TypeScript types (see
117	 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
118	 * subpaths), so the product / variant / category values this page threads between base
119	 * hooks and base components have no compile-time shape *from that package*. But the shapes
120	 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
121	 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
122	 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
123	 * Definitions rule says to import those directly. Deferred to a follow-up only because the
124	 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
125	 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
126	 */
127	type SfccProduct = any;
128	type SfccVariant = any;
129	type SfccCategory = any;
130	
131	/*
132	 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
133	 * the base JS page satisfies (it types several always-present values as optional, and takes
134	 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
135	 * below exist only to reconcile that; each passes exactly the value the base file passes, so
136	 * none of them changes runtime behaviour.
137	 */
138	
139	/** A basket line item as this page assembles it before handing it to the baskets API. */
140	type BasketLineItem = {
141	  productId?: string;
142	  id?: string;
143	  price?: number;
144	  quantity?: number;
145	  inventoryId?: string;
146	  shipmentId?: string;
147	  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
148	};
149	
