151	type ChildProductSelection = {
152	  product?: SfccProduct;
153	  variant?: SfccVariant;
154	  quantity?: number;
155	};
156	
157	/** The imperative handle ProductView exposes for set/bundle child validation. */
158	type ChildProductRef = {
159	  ref: HTMLDivElement | null;
160	  validateOrderability: ProductViewRefScope['validateOrderability'];
161	};
162	
163	/** One row of the array the base ProductView passes to `addToCart`. */
164	type ProductSelectionValue = {
165	  product?: SfccProduct;
166	  variant?: SfccVariant;
167	  quantity?: number;
168	};
169	
170	/**
171	 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
172	 * page reads to map an API status onto an SSR-visible HTTP error.
173	 */
174	type CommerceApiError = Error & { response?: { status?: number } };
175	
176	/** One value of a colour variation attribute as SFCC shapes it on the `values` array. */
177	type SfccSwatchAttrValue = {
178	  value?: string;
179	  name?: string;
180	  image?: { disBaseLink?: string; link?: string };
181	  href?: string;
182	  orderable?: boolean;
183	};
184	
185	const ProductDetail = () => {
186	  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
187	  // the rule cannot see that. `formatNumber` is SFCC-89's addition; the base file destructures
188	  // `formatMessage` alone. It feeds `formatPrice` below.
189	  // eslint-disable-next-line @typescript-eslint/unbound-method
190	  const { formatMessage, formatNumber } = useIntl();
191	  const history = useHistory();
192	  const location = useLocation();
193	  const einstein = useEinstein();
194	  const dataCloud = useDataCloud();
195	  const activeData = useActiveData();
196	  const toast = useToast();
197	  const navigate = useNavigation();
198	  const customerId = useCustomerId();
199	  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
200	  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;
201	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
202	
203	  /****************************** Basket *********************************/
204	  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
205	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
206	  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
207	  const { res } = useServerContext();
208	  if (res) {
209	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
210	  }
211	
212	  /*************************** Pick up in Store ********************/
213	  const { selectedStore } = useSelectedStore();
214	  const selectedInventoryId = selectedStore?.inventoryId || null;
215	
216	  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);
217	
218	  /*************************** Multiship ********************/
219	  const { getShipmentIdForItems } = useMultiship(basket);
220	
221	  /*************************** Product Detail and Category ********************/
222	  const { productId } = useParams<{ productId?: string }>();
223	  const urlParams = new URLSearchParams(location.search);
224	  // SDK param widening — this component only mounts on `/product/:productId`, so one of the
225	  // two is always present. `useParams` types every segment optional by design — see the
226	  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
227	  const requestedProductId = (urlParams.get('pid') || productId) as string;
228	  const {
229	    data: productResponse,
230	    isLoading: isProductLoading,
231	    isError: isProductError,
232	    error: productError,
233	  } = useProduct(
234	    {
235	      parameters: {
236	        id: requestedProductId,
237	        perPricebook: true,
238	        expand: [
239	          'availability',
240	          'promotions',
241	          'options',
242	          'images',
243	          'prices',
244	          'variations',
245	          'set_products',
246	          'bundled_products',
247	          'page_meta_tags',
248	        ],
249	        allImages: true,
250	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
251	      },
252	    },
253	    {
254	      // When shoppers select a different variant (and the app fetches the new data),
255	      // the old data is still rendered (and not the skeletons).
256	      //
257	      // Load-bearing for accessibility, beyond the loading behaviour it was added for. The price
258	      // carries `aria-live` (zimmProductPrice), and a live region only announces a change if the
259	      // region already existed — a region inserted together with its content is silent. Keeping
260	      // the previous data means `ZimmProductContent` (rendered by the `StaticProductHeader`
261	      // partial) never unmounts on a variant change, so the price element survives and React
262	      // mutates its text in place, which is what gets announced.
263	      // Remove this option and the region is destroyed and rebuilt on every swatch click, and the
264	      // price stops being announced (WCAG 2.2 AA 4.1.3). No gate catches that: the atom's own test
265	      // renders it directly, and axe sees a well-formed region either way.
266	      keepPreviousData: true,
267	    },
268	  );
269	
270	  // Note: Since category needs id from product detail, it can't be server side rendered atm
271	  // until we can do dependent query on server
272	  const {
273	    data: category,
274	    isError: isCategoryError,
275	    error: categoryError,
276	  } = useCategory({
277	    parameters: {
278	      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
279	      // in the base file.
280	      id: productResponse?.primaryCategoryId as string,
281	      levels: 1,
282	    },
283	  });
284	
285	  /****************************** Colour Swatches (SFCC-91) ***********************/
286	  // urlColour is the query-string colour param, read on every render so it is always current.
287	  // It is the only signal the ZimmColourSwatchGroup molecule needs — the atom navigates via
288	  // <Link to={href}>, updating the URL, and useDerivedProduct inside ProductView picks it up.
289	  const urlColour = new URLSearchParams(location.search).get(COLOUR_VARIATION_ATTRIBUTE_ID) ?? undefined;
290	
291	  /****************************** Sets and Bundles *********************************/
292	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
293	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
294	    {},
295	  );
296	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
297	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
298	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
299	  // which throws if the API ever returns a product without `type` (the SDK types it optional).
300	  // The two only differ in that already-broken case.
301	  const isProductASet = productResponse?.type?.set;
302	  const isProductABundle = productResponse?.type?.bundle;
303	
304	  const childVariantIds =
305	    isProductABundle || isProductASet
306	      ? Object.keys(childProductSelection)?.map(
307	          (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
308	        )
309	      : [];
310	
311	  const { data: variantProductData } = useProducts(
312	    {
313	      parameters: {
314	        // SDK param widening — the base file joins the ids itself and the SDK forwards the
315	        // value verbatim into the query string.
316	        ids: childVariantIds.join(',') as unknown as string[],
317	        allImages: false,
318	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
319	        expand: ['availability', 'variations'],
320	        select: '(data.(id,inventory,inventories,master))',
321	      },
322	    },
323	    {
324	      enabled: childVariantIds.length > 0,
325	      keepPreviousData: true,
326	    },
327	  );
328	
329	  const product: SfccProduct = useProductInventory(
330	    productResponse,
331	    variantProductData,
332	    selectedInventoryId,
333	    isProductASet,
334	    isProductABundle,
335	  );
336	
337	  /**************** Error Handling ****************/
338	
339	  if (isProductError) {
340	    const errorStatus = (productError as CommerceApiError | null)?.response?.status;
341	    switch (errorStatus) {
342	      case 404:
343	        throw new HTTPNotFound('Product Not Found.');
344	      default:
345	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
346	    }
347	  }
348	  if (isCategoryError) {
349	    const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
350	    switch (errorStatus) {
351	      case 404:
352	        throw new HTTPNotFound('Category Not Found.');
353	      default:
354	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
355	    }
356	  }
357	
358	  const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
359	  const variant = useVariant(product);
360	
361	  // SFCC-194 — Was/Now sale price.
362	  //
363	  // Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
364	  //
365	  //   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
366	  //   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
367	  //                                              variant which lacks tieredPrices reliably)
368	  //
369	  // Strategy: keep the master product's variants[] as the authoritative tieredPrices source.
370	  // Filter them by pid (exact) or colour (set) from the URL, then call getPriceData on the
371	  // scoped result. This is overridden into renderHeader so the base ProductView's own
372	  // getPriceData call (which reads the standalone variant and loses tieredPrices) is bypassed.
373	  const masterProductRef = useRef<SfccProduct | null>(null);
374	  useEffect(() => {
375	    // Guard matches exactly what the memo reads from the cache: id (for the
376	    // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
377	    // response that satisfies type.master but lacks either field is not useful — skip it
378	    // rather than writing a cache entry that would fall through to the deep-link fallback
379	    // one guard too late.
380	    if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
381	      masterProductRef.current = productResponse;
382	    }
383	  }, [productResponse]);
384	
385	  const urlPid = urlParams.get('pid') ?? undefined;
386	  const variantScopedPriceData = useMemo(
387	    () => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour),
388	    // Re-runs when the fetched product changes (standalone variant arrives) or the URL
389	    // selection changes — both are signals the displayed price must update.
390	    // masterProductRef is a ref so it is intentionally absent from deps.
391	
392	    [urlPid, urlColour, product],
393	  );
394	
395	  // True while keepPreviousData holds stale product data during a variant re-fetch (size
396	  // selection). The fetched product id hasn't caught up with the URL yet, so any price
397	  // derived from the old product is unreliable — suppress it entirely until the fetch
398	  // settles rather than showing a briefly-incorrect Was/Now figure.
399	  const isPriceStale = requestedProductId !== product?.id;
400	
401	  // This page uses the `primaryCategoryId` to retrieve the category data. This attribute
402	  // is only available on `master` products. Since a variation will be loaded once all the
403	  // attributes are selected (to get the correct inventory values), the category information
404	  // is overridden. This will allow us to keep the initial category around until a different
405	  // master product is loaded.
406	  useEffect(() => {
407	    if (category) {
408	      setPrimaryCategory(category);
409	    }
410	  }, [category]);
411	
412	  /**************** Product Variant ****************/
413	  useEffect(() => {
414	    if (!variant) {
415	      return;
416	    }
417	    // update the variation attributes parameter on
418	    // the url accordingly as the variant changes
419	    const updatedUrl = rebuildPathWithParams(`${location.pathname}${location.search}`, {
420	      pid: variant?.productId,
421	    });
422	    history.replace(updatedUrl);
423	  }, [variant]);
424	
425	  /**************** Wishlist ****************/
426	  const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
