523	      if (
524	        productItems.some(
525	          // Index-type assertion, not one of the "SDK param widening" casts described above:
526	          // `pickupInStoreMap` is this page's own `Record<string, boolean>` state, and
527	          // `item.productId || item.id` is `string | undefined` on `BasketLineItem`, which
