999	              )
1000	            }
1001	          </Fragment>
1002	        ) : (
1003	          <Fragment>
1004	            <Island hydrateOn={'visible'}>
1005	              <ProductView
1006	                product={product}
1007	                category={primaryCategory?.parentCategoryTree || []}
1008	                renderVariationAttribute={(attr) => {
1009	                  if (attr.id !== COLOUR_VARIATION_ATTRIBUTE_ID) return undefined;
1010	                  const values = (attr.values ?? []).map((v: SfccSwatchAttrValue) => ({
1011	                    value: v.value ?? '',
1012	                    name: v.name ?? v.value ?? '',
1013	                    imageUrl: v.image?.disBaseLink || v.image?.link,
1014	                    href: v.href ?? undefined,
1015	                    orderable: v.orderable ?? true,
1016	                  }));
1017	
1018	                  // SFCC-708 — append related-colour swatches from the SCAPI-enriched
1019	                  // c_relatedSwatches field. The backend already filters out invalid and
1020	                  // offline products, so every item here is safe to render. Each swatch
1021	                  // links to a different master product via a full page reload (forceReload).
1022	                  // `c_relatedSwatches` is a Zimmermann SCAPI attribute absent from the SDK
1023	                  // types — the cast is safe because the backend guarantees this shape.
1024	                  const relatedSwatches = buildRelatedSwatches(
1025	                    (product?.c_relatedSwatches ?? []) as RelatedSwatch[],
1026	                    productUrlBuilder,
1027	                    COLOUR_VARIATION_ATTRIBUTE_ID,
1028	                  );
1029	                  const allValues = [...values, ...relatedSwatches];
1030	                  // Skeleton height approximates the rendered swatch group:
1031	                  // label row (var(--zimm-scale-xl) = 24px) + gap (8px) + swatch row (48px).
1032	                  return (
1033	                    <Suspense fallback={<Skeleton height="80px" />}>
1034	                      <ZimmColourSwatchGroup
1035	                        values={allValues}
1036	                        selectedValue={urlColour}
1037	                        label={attr.name ?? 'Colour'}
1038	                      />
1039	                    </Suspense>
1040	                  );
1041	                }}
1042	                renderHeader={(headerProps) => (
1043	                  <StaticProductHeader
1044	                    {...headerProps}
1045	                    priceData={isPriceStale ? null : variantScopedPriceData ?? headerProps.priceData}
1046	                    isPriceLoading={isPriceStale}
1047	                  />
1048	                )}
1049	                addToCart={handleAddToCart}
1050	                addToWishlist={handleAddToWishlist}
1051	                isProductLoading={isProductLoading}
1052	                isBasketLoading={isBasketLoading}
1053	                isWishlistLoading={isWishlistLoading}
1054	                childProductOrderability={childProductOrderability}
1055	                setChildProductOrderability={setChildProductOrderability}
1056	                setSelectedBundleQuantity={setSelectedBundleQuantity}
1057	                selectedBundleParentQuantity={selectedBundleQuantity}
1058	                pickupInStore={!!pickupInStoreMap[product?.id]}
1059	                setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
1060	                onOpenStoreLocator={onOpenStoreLocator}
1061	                showDeliveryOptions={storeLocatorEnabled}
1062	                footerLinks={
1063	                  // `ZimmProductMeta` renders here, not in a separate Box below `<Island>` (where
1064	                  // `InformationAccordion` used to share one with it) — that positioned it as a
1065	                  // full-width block below the *whole* ProductView (both the image gallery and
1066	                  // info columns), so it rendered flush left instead of inside the info column,
1067	                  // a real bug Tim caught by comparing the running page against Figma. Its own
1068	                  // recipe (`zimmProductMeta.css.ts`'s `SPACE_META_ROW`/`paddingTop`) already
1069	                  // supplies the 28px gap from the trigger rows above it — nothing extra needed
1070	                  // here for that hop.
1071	                  <>
1072	                    <PdpFooterLinks
1073	                      triggers={pdpDrawerTabs.map(({ id, label }) => ({ id, label }))}
1074	                      onTriggerClick={openPdpDrawerAtTab}
1075	                      findInBoutiqueLabel={findInBoutiqueLabel}
1076	                      onFindInBoutiqueClick={openBoutiqueDrawer}
1077	                    />
1078	                    <ZimmProductMeta modelInfo={staticInfo?.modelInfo} styleCode={staticInfo?.styleCode} />
1079	                  </>
1080	                }
1081	              />
1082	
1083	              <ZimmPdpDrawer
1084	                key={activePdpTabId ?? 'closed'}
1085	                isOpen={isPdpDrawerOpen}
1086	                onClose={closePdpDrawer}
1087	                size="large"
1088	                tabs={pdpDrawerTabs}
1089	                initialTabId={activePdpTabId ?? undefined}
1090	                ariaLabel={pdpDrawerAriaLabel}
1091	              />
1092	              <ZimmDrawer
1093	                isOpen={isBoutiqueDrawerOpen}
1094	                onClose={closeBoutiqueDrawer}
1095	                size="small"
1096	                aria-label={findInBoutiqueLabel}
1097	              >
1098	                <Box padding="var(--zimm-scale-xl)">{comingSoon}</Box>
1099	              </ZimmDrawer>
1100	            </Island>
1101	          </Fragment>
1102	        )}
1103	
1104	        {/* Product Recommendations */}
1105	        <Stack spacing={16}>
1106	          {!isProductASet && (
1107	            <Island hydrateOn={'visible'}>
1108	              <RecommendedProducts
1109	                title={
1110	                  <FormattedMessage
1111	                    defaultMessage="Complete the Set"
1112	                    id="product_detail.recommended_products.title.complete_set"
1113	                  />
1114	                }
1115	                recommender={EINSTEIN_RECOMMENDERS.PDP_COMPLETE_SET}
1116	                products={[product]}
1117	                mx={{ base: -4, md: -8, lg: 0 }}
1118	                shouldFetch={() => product?.id}
1119	              />
1120	            </Island>
1121	          )}
1122	          <Island hydrateOn={'visible'}>
1123	            <RecommendedProducts
1124	              title={
1125	                <FormattedMessage
1126	                  defaultMessage="You might also like"
1127	                  id="product_detail.recommended_products.title.might_also_like"
1128	                />
1129	              }
1130	              recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE}
1131	              products={[product]}
1132	              mx={{ base: -4, md: -8, lg: 0 }}
1133	              shouldFetch={() => product?.id}
1134	            />
1135	          </Island>
1136	
1137	          <Island hydrateOn={'visible'}>
1138	            <RecommendedProducts
1139	              // The Recently Viewed recommender doesn't use `products`, so instead we
1140	              // provide a key to update the recommendations on navigation.
1141	              key={location.key}
1142	              title={
1143	                <FormattedMessage
1144	                  defaultMessage="Recently Viewed"
1145	                  id="product_detail.recommended_products.title.recently_viewed"
1146	                />
1147	              }
1148	              recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
1149	              mx={{ base: -4, md: -8, lg: 0 }}
1150	            />
1151	          </Island>
1152	        </Stack>
1153	      </Stack>
1154	    </Box>
1155	  );
1156	};
1157	
1158	ProductDetail.getTemplateName = () => 'product-detail';
1159	
1160	/*
1161	 * The base file declares `ProductDetail.propTypes = {match: PropTypes.object}` purely as
1162	 * documentation — the component takes no props and never reads `match`. The TypeScript
1163	 * signature above expresses the same thing at compile time, so the runtime `prop-types`
1164	 * declaration is not carried over.
1165	 */
1166	
1167	export default ProductDetail;
