/**
 * Selects the correct `getPriceData` result for the PDP given the current product, the cached
 * master, and the active URL parameters.
 *
 * Extracted from the page's `useMemo` so the filtering and fallback logic is unit-testable
 * without mounting a React component or mocking any hooks. The page's memo reduces to a
 * single call:
 *
 *   `useMemo(() => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour), [...])`
 *
 * Nothing else on the PDP ties URL params to a pricing result, and a mis-keyed filter here
 * silently shows the wrong Was/Now — not a crash, not a blank, just wrong data. That is the
 * failure mode `productInfo.ts`'s docblock describes for field mapping; the same reasoning
 * applies here.
 */
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';

/**
 * A variant entry as this selector reads it.
 * Only the two fields that drive the colour/pid filters are typed;
 * everything else is spread into `getPriceData` unchanged.
 */
export type ScopedVariant = {
  productId?: string;
  variationValues?: Record<string, string | undefined>;
  [key: string]: unknown;
};

/**
 * The subset of a product response this selector reads.
 * Every field optional — absent fields are treated as absent, not as errors.
 * Fields beyond this shape are spread into `getPriceData` unchanged.
 */
export type ScopedProduct = {
  id?: string;
  master?: { masterId?: string };
  variants?: ScopedVariant[];
  tieredPrices?: unknown[];
  [key: string]: unknown;
};

/**
 * Returns the `getPriceData` result scoped to the variants that match the current URL
 * selection, or `null` when no matching selection exists.
 *
 * @param product - The resolved product (master when colour-only; standalone variant when a
 *   size is picked and `pid` is in the URL).
 * @param cachedMaster - The last master product stored in `masterProductRef`, or `null`.
 *   Used as the variant source when `product` has switched to a standalone variant that may
 *   lack `tieredPrices`.
 * @param urlPid - The `pid` URL parameter, if present.
 * @param urlColour - The `color` URL parameter, if present.
 */
export const selectVariantScopedPriceData = (
  product: ScopedProduct | null | undefined,
  cachedMaster: ScopedProduct | null,
  urlPid: string | undefined,
  urlColour: string | undefined,
) => {
  // ── Cached-master path (believed unreachable — see note below) ────────────────
  //
  // This path exists on the assumption that a standalone-variant SFCC response may lack
  // `variants[]`, requiring a cached master to supply them. However, `use-variation-
  // attributes.js:162` in the base app accesses `product.variants.filter(...)` completely
  // unguarded on every render. If any product type ever returned without `variants[]`, the
  // base PDP would throw on every size selection. It doesn't — so SFCC always populates
  // `variants[]`, and `product?.variants?.length` is always truthy on the next line. That
  // means `effectiveCachedMaster` is never consulted, and the deep-link fallback below it
  // never fires.
  //
  // The knock-on at the getPriceData call: when product is a variant (colour+size, pid in
  // URL), `getPriceData` ignores the injected `variants` array anyway — `findLowestPrice`
  // checks `type.master` and uses `[product]` for non-masters (product-utils.js:257). Was/Now
  // for the colour+size case comes from the variant's own `tieredPrices` (present because we
  // request `perPricebook:true`), not from the master variants we inject. The active path for
  // colour+size pricing is therefore the variant's own prices, regardless of this cache.
  //
  // Left in place pending a dev-org verification that variant responses always include
  // `variants[]`. Once confirmed, the `cachedMaster` parameter, `cachedMasterMatchesCurrent`,
  // `effectiveCachedMaster`, the deep-link fallback block, and the corresponding `useEffect`
  // + `masterProductRef` in `product-detail/index.tsx` can all be removed —
  // `masterVariants`/`masterProduct` would simply become `product.variants` and `product`.
  const cachedMasterMatchesCurrent =
    cachedMaster != null && (product?.id === cachedMaster.id || product?.master?.masterId === cachedMaster.id);
  const effectiveCachedMaster = cachedMasterMatchesCurrent ? cachedMaster : null;

  const masterVariants = product?.variants?.length ? product.variants : effectiveCachedMaster?.variants;
  const masterProduct = product?.variants?.length ? product : effectiveCachedMaster;

  // Deep-link fallback — see unreachability note above.
  if (!masterProduct || !masterVariants?.length) {
    if ((urlPid || urlColour) && product?.tieredPrices?.length) {
      return getPriceData(product);
    }
    return null;
  }

  let matchingVariants: ScopedVariant[];
  if (urlPid) {
    const pidVariants = masterVariants.filter((v) => v.productId === urlPid);
    // Cross-check: if a colour is also selected, verify the pid variant belongs to it.
    //
    // When a shopper switches colour and the current size doesn't exist in the new colour,
    // `useVariant` matches nothing and the pid-rewriting effect bails out early
    // (`if (!variant) return`), leaving the URL with a stale pid still pointing at the
    // previous colour's variant. Using it unchecked would show the previous colour's
    // Was/Now price while the new colour is visually selected.
    //
    // If the pid variant's colour doesn't match urlColour (or the pid matched nothing),
    // fall back to colour-only pricing until the shopper picks a valid size in the new
    // colour and the pid is correctly rewritten.
    const pidColour = pidVariants[0]?.variationValues?.color;
    const pidIsStale = urlColour && (pidVariants.length === 0 || pidColour !== urlColour);
    matchingVariants = pidIsStale ? masterVariants.filter((v) => v.variationValues?.color === urlColour) : pidVariants;
  } else if (urlColour) {
    // Colour selected, size not yet — price spans all sizes for this colour
    matchingVariants = masterVariants.filter((v) => v.variationValues?.color === urlColour);
  } else {
    return null; // no selection yet
  }

  if (!matchingVariants.length) return null;
  return getPriceData({ ...masterProduct, variants: matchingVariants });
};

